export function matchesQuery(item, query) {
  // AI-code-start lines:6 tool:Codex
  // 将关键词和可搜索字段统一归一化，避免缺失字段中断筛选。
  const normalizedQuery = query.trim().toLowerCase();
  if (normalizedQuery === '') return true;
  return [item.name ?? '', item.code ?? ''].some((value) =>
    String(value).toLowerCase().includes(normalizedQuery),
  );
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { matchesQuery } from '../src/search.js';

test('[TC-01] 名称精确匹配', () => {
  assert.equal(matchesQuery({ name: 'Alpha', code: 'A-01' }, 'Alpha'), true);
});

// AI-code-start lines:10 tool:Codex
test('[TC-02] 归一化匹配、空关键词与缺失字段', () => {
  // 集中覆盖名称、编码与空值边界，避免遗漏任一可搜索字段。
  const item = { name: 'Alpha Project', code: 'PRJ-42' };
  assert.equal(matchesQuery(item, '  alpha  '), true);
  assert.equal(matchesQuery(item, 'prj-42'), true);
  assert.equal(matchesQuery(item, '   '), true);
  assert.equal(matchesQuery({ code: 'ONLY-CODE' }, 'only-code'), true);
  assert.equal(matchesQuery({ name: 'Only Name' }, 'only name'), true);
  assert.equal(matchesQuery({ name: 'Alpha' }, 'missing'), false);
});
